func loadOpts(t *testing.T, tomlBody string) *ffuf.ConfigOptions {
	t.Helper()
	if tomlBody == "" {
		return ffuf.NewConfigOptions()
	}
	f := filepath.Join(t.TempDir(), "ffufrc")
	if err := os.WriteFile(f, []byte(tomlBody), 0644); err != nil {
		t.Fatal(err)
	}
	opts, err := ffuf.ReadConfig(f)
	if err != nil {
		t.Fatalf("ReadConfig: %v", err)
	}
	return opts
}

func snapshotConfig(conf *ffuf.Config, err error, cwd string) string {
	var b strings.Builder
	if err != nil {
		fmt.Fprintf(&b, "error: %s\n", err.Error())
	}
	if conf == nil {
		return b.String()
	}
	j, _ := json.MarshalIndent(conf, "", "  ")
	s := string(j)
	if cwd != "" {
		s = strings.ReplaceAll(s, cwd, "$CWD")
	}
	b.WriteString(s)
	b.WriteString("\n")
	return b.String()
}

func matcherSnapshot(conf *ffuf.Config) string {
	if conf.MatcherManager == nil {
		return "(no matcher manager)\n"
	}
	var b strings.Builder
	dump := func(title string, providers map[string]ffuf.FilterProvider) {
		reprs := make([]string, 0, len(providers))
		for name, p := range providers {
			reprs = append(reprs, fmt.Sprintf("  %s = %s", name, p.Repr()))
		}
		sort.Strings(reprs)
		fmt.Fprintf(&b, "%s:\n%s\n", title, strings.Join(reprs, "\n"))
	}
	dump("matchers", conf.MatcherManager.GetMatchers())
	dump("filters", conf.MatcherManager.GetFilters())
	return b.String()
}

// captureStdout redirects os.Stdout for the duration of fn and returns what it wrote.
// The read end is drained while fn runs, not after it returns: fn's output can be
// larger than the pipe buffer, and a write that fills the buffer blocks until
// something reads from it.
func captureStdout(fn func()) string {
	r, w, _ := os.Pipe()
	old := os.Stdout
	os.Stdout = w
	captured := make(chan string, 1)
	go func() {
		var buf bytes.Buffer
		_, _ = io.Copy(&buf, r)
		captured <- buf.String()
	}()
	fn()
	_ = w.Close()
	os.Stdout = old
	out := <-captured
	_ = r.Close()
	return out
}

// TestCaptureStdoutHandlesOutputLargerThanThePipeBuffer guards the regression that
// kept the help golden test off the Windows matrix: captureStdout wrote all of fn's
// output before reading any of it, so an output bigger than the pipe buffer blocked
// forever. A megabyte is larger than that buffer on every platform CI runs on, so a
// reintroduced regression shows up as the package hitting its test timeout, with the
// blocked write named in the goroutine dump.
func TestCaptureStdoutHandlesOutputLargerThanThePipeBuffer(t *testing.T) {
	payload := strings.Repeat("ffuf", 1<<18) // 1 MiB
	if got := captureStdout(func() { fmt.Print(payload) }); got != payload {
		t.Errorf("captured %d bytes, want %d", len(got), len(payload))
	}
}

