		fv, err := flt.Filter(resp)
		if err != nil {
			continue
		}
		if fv {
			if filterMode == "or" {
				// return early, as a filter matched
				return false
			}
		} else {
			if filterMode == "and" {
				// return early, as not all filters matched in "and" mode
				return true
			}
		}
	}
	if len(filters) > 0 && filterMode == "and" {
		// we did not return early, so all filters were matched
		return false
	}
	return true
