	// single deterministic pass.
	if len(vars) > 0 {
		rep := varsReplacer(vars)
		method = rep.Replace(method)
		path = rep.Replace(path)
		body = []byte(rep.Replace(string(body)))
		host = rep.Replace(host)
		for h, v := range headers {
			headers[h] = rep.Replace(v)
		}
