func (s *Stdoutput) Cycle() {
	s.resultMutex.Lock()
	s.Results = append(s.Results, s.CurrentResults...)
	s.CurrentResults = make([]ffuf.Result, 0)
	s.resultMutex.Unlock()
}

// GetResults returns the result slice
