		sort.Slice(values, func(i, j int) bool { return len(values[i]) > len(values[j]) })
		for _, value := range values {
			data = bytes.ReplaceAll(data, []byte(value), []byte{0})
		}
	}

	out := make([]byte, 0, len(data))
	inSpace := false
	for _, b := range data {
		switch b {
		case ' ', '\t', '\r', '\n':
			if !inSpace {
				out = append(out, ' ')
				inSpace = true
			}
		default:
			inSpace = false
			if b >= 'A' && b <= 'Z' {
				b += 'a' - 'A'
			}
			out = append(out, b)
		}
	}
	return out
}

func fingerprintSimilarity(a, b responseFingerprint) float64 {
	if a.status != b.status || a.contentType != b.contentType {
		return 0
	}
	if a.empty || b.empty {
		if a.empty && b.empty && a.exact == b.exact {
			return 1
		}
		return 0
	}
	if a.exact == b.exact {
		return 1
	}
	if a.hashCount == 0 || b.hashCount == 0 {
		return 0
	}
	denom := a.hashCount
	if b.hashCount > denom {
		denom = b.hashCount
	}
	matches := 0
	for i := 0; i < a.hashCount && i < b.hashCount; i++ {
		if a.minhash[i] == b.minhash[i] {
			matches++
		}
	}
	return float64(matches) / float64(denom)
}

func minhash(data []byte) ([clusterMinhashSize]uint64, int) {
	var values [clusterMinhashSize]uint64
	count := 0
	maxIndex := 0
	add := func(h uint64) {
		if count < clusterMinhashSize {
			values[count] = h
			if count == 0 || h > values[maxIndex] {
				maxIndex = count
			}
			count++
			return
		}
		if h < values[maxIndex] {
			values[maxIndex] = h
			maxIndex = 0
			for i := 1; i < clusterMinhashSize; i++ {
				if values[i] > values[maxIndex] {
					maxIndex = i
				}
			}
		}
	}

