	for i := 0; i < clusterShingleSize; i++ {
		h = h*clusterHashPrime + uint64(data[i])
	}
	add(h)
	power := uint64(1)
	for i := 0; i < clusterShingleSize-1; i++ {
		power *= clusterHashPrime
	}
	for i := clusterShingleSize; i < len(data); i++ {
		h = (h-uint64(data[i-clusterShingleSize])*power)*clusterHashPrime + uint64(data[i])
		add(h)
	}
	return values, count
}

func hashBytes(data []byte) uint64 {
	var h uint64 = 14695981039346656037
	for _, b := range data {
		h ^= uint64(b)
		h *= clusterHashPrime
	}
	return h
}

func clusterScope(resp *Response) string {
	if resp == nil || resp.Request == nil {
		return ""
	}
	if parsed, err := url.Parse(resp.Request.Url); err == nil && parsed.Host != "" {
		return strings.ToLower(parsed.Host)
	}
	return strings.ToLower(resp.Request.Host)
}

